// ===================== state serializers =====================

fn tank_value(t: &Tank) -> Value {
    obj(vec![
        ("hp", int(t.hp)),
        ("max_hp", int(t.max_hp)),
        ("armor", int(t.armor)),
        ("dodge_num", int(t.dodge_num as i64)),
        ("dodge_den", int(t.dodge_den as i64)),
        ("mana_shield", int(t.mana_shield)),
        ("mana_shield_max", int(t.mana_shield_max)),
        ("mana_regen_per_tick", int(t.mana_regen_per_tick)),
        ("hp_regen_per_tick", int(t.hp_regen_per_tick)),
        ("spikes_damage", int(t.spikes_damage)),
        ("spikes_mult", hex(t.spikes_mult.raw())),
        ("shield_active_dr", hex(t.shield_active_dr.raw())),
        ("heal_on_damaged", int(t.heal_on_damaged)),
        ("heal_on_kill", int(t.heal_on_kill)),
        ("mana_on_kill", int(t.mana_on_kill)),
        ("heal_on_poison", int(t.heal_on_poison)),
        ("healing_mult", hex(t.healing_mult.raw())),
        ("missing_hp_heal_pct", hex(t.missing_hp_heal_pct.raw())),
        ("revives", int(t.revives as i64)),
        ("revive_bonus_hp", int(t.revive_bonus_hp)),
        ("shieldbreak_stun_range", int(t.shieldbreak_stun_range)),
        ("shieldbreak_stun_ticks", int(t.shieldbreak_stun_ticks as i64)),
        ("spikes_poison_dps", int(t.spikes_poison_dps)),
        ("spikes_poison_ticks", int(t.spikes_poison_ticks as i64)),
        ("spikes_stack_per", int(t.spikes_stack_per)),
        ("spikes_stacks", int(t.spikes_stacks as i64)),
        ("spikes_stacks_max", int(t.spikes_stacks_max as i64)),
        ("aura_range", int(t.aura_range)),
        ("aura_cadence", int(t.aura_cadence as i64)),
        ("aura_damage", int(t.aura_damage)),
        ("aura_poison_dps", int(t.aura_poison_dps)),
        ("aura_poison_ticks", int(t.aura_poison_ticks as i64)),
        ("aura_tick", int(t.aura_tick as i64)),
    ])
}

fn economy_value(e: &Economy) -> Value {
    obj(vec![
        ("gold", int(e.gold)),
        ("income_per_tick", int(e.income_per_tick)),
        ("income_mult", hex(e.income_mult.raw())),
        ("income_regen_pct", hex(e.income_regen_pct.raw())),
        ("bounty_mult", hex(e.bounty_mult.raw())),
        ("bounty_proc_chance_pct", int(e.bounty_proc_chance_pct)),
        ("bounty_proc_bonus", hex(e.bounty_proc_bonus.raw())),
        ("gold_per_damage", hex(e.gold_per_damage.raw())),
        ("income_shield_pct", hex(e.income_shield_pct.raw())),
    ])
}

fn modifiers_value(m: &Modifiers) -> Value {
    obj(vec![
        ("add_global", hex(m.add_global.raw())),
        ("add_by_type", Value::Arr(m.add_by_type.iter().map(|f| hex(f.raw())).collect())),
        ("add_by_scope", Value::Arr(m.add_by_scope.iter().map(|f| hex(f.raw())).collect())),
        ("mul_global", hex(m.mul_global.raw())),
        ("attack_speed", hex(m.attack_speed.raw())),
        ("vs_stunned", hex(m.vs_stunned.raw())),
        ("vs_poisoned", hex(m.vs_poisoned.raw())),
        ("poison_dmg_mult", hex(m.poison_dmg_mult.raw())),
        ("stun_dur_mult", hex(m.stun_dur_mult.raw())),
        (
            "weapon_count_scaling",
            Value::Arr(
                m.weapon_count_scaling
                    .iter()
                    .map(|r| {
                        obj(vec![
                            ("weapon_def", int(r.weapon_def as i64)),
                            ("dmg_type", int(r.dmg_type as i64)),
                            ("per", hex(r.per.raw())),
                        ])
                    })
                    .collect(),
            ),
        ),
        ("dmg_per_maxhp_rate", hex(m.dmg_per_maxhp_rate.raw())),
        ("dmg_per_bounty_rate", hex(m.dmg_per_bounty_rate.raw())),
        ("shield_active_dmg", hex(m.shield_active_dmg.raw())),
    ])
}

// ===================== case setup =====================

/// Force a pre-state field so the clamps / ceilings / overheal paths are
/// reachable. Mirrors the `SETUP` table in `modifiers_test.luau` key for key; an
/// unknown key is a loud panic rather than a silently skipped case.
fn apply_setup(s: &mut ArenaState, key: &str, v: i64) {
    match key {
        "gold" => s.economy.gold = v,
        "income_per_tick" => s.economy.income_per_tick = v,
        "bounty_proc_chance_pct" => s.economy.bounty_proc_chance_pct = v,
        "hp" => s.tank.hp = v,
        "max_hp" => s.tank.max_hp = v,
        "armor" => s.tank.armor = v,
        "mana_shield" => s.tank.mana_shield = v,
        "mana_shield_max" => s.tank.mana_shield_max = v,
        "heal_on_kill" => s.tank.heal_on_kill = v,
        "mana_on_kill" => s.tank.mana_on_kill = v,
        "revives" => s.tank.revives = v as u32,
        "revive_bonus_hp" => s.tank.revive_bonus_hp = v,
        "hp_regen_per_tick" => s.tank.hp_regen_per_tick = v,
        "mana_regen_per_tick" => s.tank.mana_regen_per_tick = v,
        "dodge_den" => s.tank.dodge_den = v as u32,
        "aura_cadence" => s.tank.aura_cadence = v as u32,
        "tick" => s.tick = v as u32,
        "dead" => s.dead = v != 0,
        other => panic!("oracle: unknown setup key {other:?}"),
    }
}

/// `Fixed`-valued twin of [`apply_setup`] (the `FIXED_SETUP` table in the Luau).
fn apply_fixed_setup(s: &mut ArenaState, key: &str, v: Fixed) {
    match key {
        "income_mult" => s.economy.income_mult = v,
        "income_regen_pct" => s.economy.income_regen_pct = v,
        "income_shield_pct" => s.economy.income_shield_pct = v,
        "bounty_mult" => s.economy.bounty_mult = v,
        "bounty_proc_bonus" => s.economy.bounty_proc_bonus = v,
        "healing_mult" => s.tank.healing_mult = v,
        other => panic!("oracle: unknown fixed setup key {other:?}"),
    }
}

fn arsenal(defs: &[u16]) -> Vec<WeaponInstance> {
    defs.iter()
        .map(|&def| WeaponInstance { instance_id: EntityId(0), def, next_fire_tick: 0 })
        .collect()
}

/// `n` copies of one effect — the deep multiplicative / bundle stacks below are
/// long enough that spelling them out would bury the table.
fn rep(e: E, n: usize) -> Vec<E> {
    vec![e; n]
}

/// `n` repetitions of the `[+2000 flat Max HP, +25% Max HP]` purchase bundle: the
/// stack that drives the `SOFT^3 / mag^3` intermediate past 2^53, where a port that
/// lets it land in a raw Luau number goes silently wrong.
fn maxhp_bundle(n: usize) -> Vec<E> {
    let mut v = Vec::with_capacity(n * 2);
    for _ in 0..n {
        v.push(E::MaxHp(2000));
        v.push(E::MaxHpPct(25, 100));
    }
    v
}

// ===================== effect cases =====================

struct EffectCase {
    name: &'static str,
    setup: Vec<(&'static str, i64)>,
    effects: Vec<E>,
    arsenal: Vec<u16>,
    /// Emit `weapon_damage_mult` over the WHOLE catalog. Only the handful of cases
    /// that actually move a per-type / per-scope additive need it; for the rest it
    /// would be 86 copies of the same number per case.
    all_weapons: bool,
    /// Weapon def whose `on_hit` is pushed through `scale_on_hit`.
    on_hit_def: u16,
}

#[allow(clippy::too_many_arguments)]
fn c(
    name: &'static str,
    setup: Vec<(&'static str, i64)>,
    effects: Vec<E>,
    arsenal: Vec<u16>,
    all_weapons: bool,
    on_hit_def: u16,
) -> EffectCase {
    EffectCase { name, setup, effects, arsenal, all_weapons, on_hit_def }
}

