fn econ_cases() -> Value {
    let mut out = Vec::new();
    for case in econ_case_table() {
        let mut s = ArenaState::new(case.seed, 0);
        s.modifiers = Modifiers::new();
        let rng_initial = s.rng_proc.state();
        for (k, v) in &case.setup {
            apply_setup(&mut s, k, *v);
        }
        for (k, v) in &case.fixed_setup {
            apply_fixed_setup(&mut s, k, Fixed::from_raw(*v));
        }
        s.total_gold_earned = 0;
        s.total_damage_dealt = 0;

        let mut steps = Vec::new();
        for op in &case.ops {
            match *op {
                "tick_income" => economy::tick_income(&mut s),
                "collect_bounties" => {
                    s.pending_kills = case.pending_kills.clone();
                    economy::collect_bounties(&mut s);
                }
                "resolve_deaths" => economy::resolve_deaths(&mut s),
                "on_round_start" => economy::on_round_start(&mut s),
                "zero_hp" => s.tank.hp = 0,
                other => panic!("oracle: unknown economy op {other:?}"),
            }
            steps.push(obj(vec![
                ("op", Value::Str(op.to_string())),
                (
                    "after",
                    obj(vec![
                        ("economy", economy_value(&s.economy)),
                        ("tank", tank_value(&s.tank)),
                        ("total_gold_earned", int(s.total_gold_earned)),
                        ("total_damage_dealt", int(s.total_damage_dealt)),
                        // `pending_kills` must be empty at every tick boundary, so
                        // only its LENGTH is contractual.
                        ("pending_kills", int(s.pending_kills.len() as i64)),
                        ("dead", Value::Bool(s.dead)),
                        (
                            "death_tick",
                            match s.death_tick {
                                Some(t) => int(t as i64),
                                None => Value::Null,
                            },
                        ),
                        ("rng_proc", hex_u(s.rng_proc.state())),
                    ]),
                ),
            ]));
        }

        out.push(obj(vec![
            ("name", Value::Str(case.name.to_string())),
            ("seed", hex_u(case.seed)),
            ("rng_proc_initial", hex_u(rng_initial)),
            (
                "setup",
                Value::Arr(
                    case.setup
                        .iter()
                        .map(|(k, v)| obj(vec![("k", Value::Str(k.to_string())), ("v", int(*v))]))
                        .collect(),
                ),
            ),
            (
                "fixed_setup",
                Value::Arr(
                    case.fixed_setup
                        .iter()
                        .map(|(k, v)| obj(vec![("k", Value::Str(k.to_string())), ("v", hex(*v))]))
                        .collect(),
                ),
            ),
            ("pending_kills", ints(case.pending_kills.iter().map(|&d| d as i64))),
            (
                "ops",
                Value::Arr(case.ops.iter().map(|o| Value::Str(o.to_string())).collect()),
            ),
            ("steps", Value::Arr(steps)),
        ]));
    }
    Value::Arr(out)
}

// ===================== document =====================

/// The whole oracle document.
fn oracle_document() -> Value {
    obj(vec![
        ("schema_version", int(SCHEMA_VERSION)),
        // ASSERTED by the Luau against `Content.CONTENT_HASH`: a regenerated catalog
        // must fail there loudly rather than assert the port against a fossil.
        ("content_hash", Value::Str(format!("{:016x}", super::content_hash()))),
        ("num_scopes", int(c::NUM_SCOPES as i64)),
        ("death_engine", int(c::DEATH_ENGINE as i64)),
        ("ramp_per_round", int(c::RAMP_PER_ROUND as i64)),
        ("effect_cases", effect_cases()),
        ("synergy_cases", synergy_cases()),
        ("ramp_cases", ramp_cases()),
        ("econ_cases", econ_cases()),
    ])
}

/// The oracle document as one line of canonical JSON — the single public entry
/// point of this module. Deterministic: two calls return identical bytes.
pub fn oracle_json() -> String {
    oracle_document().canonical()
}

/// `oracle_json()` wrapped as a Luau ModuleScript returning the raw text, the way
/// `export::content_data_luau` wraps `content.json`. Standalone Luau has no file
/// I/O, so `modifiers_test.luau` cannot read a `.json` — the document has to arrive
/// as a module. Generating that module (rather than pasting the JSON into the test)
/// is what stops it going stale: it already did once, and cost ten red assertions.
pub fn oracle_data_luau() -> String {
    let json = oracle_json();
    assert!(!json.contains("]==]"), "the oracle would break the Luau long-bracket literal");
    format!(
        "--!nonstrict\n\
         -- GENERATED by `cargo run -p sim --bin export-oracle` -- DO NOT EDIT.\n\
         -- Source of truth: sim-core/crates/sim/src/export/oracle.rs\n\
         -- Consumed by roblox/test/modifiers_test.luau (`roblox/CONTRACTS.md` C4).\n\
         return [==[\n{json}]==]\n"
    )
}

/// Repo-relative path of the generated artifact.
pub const ORACLE_OUTPUT: &str = "roblox/test/OracleData.luau";

#[cfg(test)]
mod tests {
    use super::*;

    /// Determinism, the same rule the other exporters hold: two runs, one answer.
    #[test]
    fn generation_is_byte_stable() {
        assert_eq!(oracle_json(), oracle_json());
    }

    /// The parser rejects any number carrying a `.`/`e`, so a successful reparse IS
    /// the "no floats anywhere" proof (C1) — and it also proves the document the
    /// Luau `Json.decode` sees is well-formed.
    #[test]
    fn document_reparses_with_no_floats() {
        let doc = Value::parse(&oracle_json()).expect("oracle document parses");
        assert_eq!(doc.at("schema_version").as_i64(), SCHEMA_VERSION);
        assert_eq!(doc.at("num_scopes").as_i64(), c::NUM_SCOPES as i64);
        assert!(!doc.at("effect_cases").as_arr().is_empty());
        assert!(!doc.at("synergy_cases").as_arr().is_empty());
        assert_eq!(doc.at("ramp_cases").as_arr().len(), RAMP_MODIFIERS.len());
        assert!(!doc.at("econ_cases").as_arr().is_empty());
    }

    /// Case names are the Luau's assertion tags; a duplicate makes a failure
    /// ambiguous and a rename silently drops coverage.
    #[test]
    fn case_names_are_unique() {
        for (what, names) in [
            ("effect", effect_case_table().iter().map(|c| c.name).collect::<Vec<_>>()),
            ("synergy", synergy_case_table().iter().map(|c| c.0).collect::<Vec<_>>()),
            ("econ", econ_case_table().iter().map(|c| c.name).collect::<Vec<_>>()),
        ] {
            let mut sorted = names.clone();
            sorted.sort_unstable();
            sorted.dedup();
            assert_eq!(sorted.len(), names.len(), "duplicate {what} case name");
        }
    }

    /// Every ramp case must name a modifier that actually ramps — otherwise the
    /// case silently degenerates into "apply_ramps on an empty list".
    #[test]
    fn every_ramp_case_modifier_ramps() {
        for &i in &RAMP_MODIFIERS {
            assert!(
                c::MODIFIERS[i as usize].ramp.is_some(),
                "MODIFIERS[{i}] ({}) no longer ramps",
                c::MODIFIERS[i as usize].name
            );
        }
    }

    /// `INCOME_REGEN_SOFT` coverage, as a property rather than a magic number: the
    /// deep `IncomeRegenPct` stack must land STRICTLY BELOW what an uncapped
    /// (linear) stack of the same copies would give. Without the knee the two are
    /// equal, so this fails if the soft cap is ever removed from that arm.
    #[test]
    fn the_income_regen_case_actually_crosses_its_knee() {
        let case = effect_case_table()
            .into_iter()
            .find(|c| c.name == "softcap_income_regen_one_hundred_fifty_gold_mines")
            .expect("the INCOME_REGEN_SOFT case is present");
        let mut s = ArenaState::new(1, 0);
        s.modifiers = Modifiers::new();
        let mut linear = Fixed::ZERO;
        for &e in &case.effects {
            s.modifiers.apply_effect(e, &mut s.economy, &mut s.tank);
            if let E::IncomeRegenPct(n, d) = e {
                linear += Fixed::from_ratio(n, d);
            }
        }
        assert!(
            s.economy.income_regen_pct < linear,
            "stack ({:?}) did not cross the knee (linear would be {:?})",
            s.economy.income_regen_pct,
            linear
        );
    }
}
